  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00083",
          "explanation": "Doctor uses non-stigmatizing language: '不必隔离', '公筷公勺', '避免密切接触婴幼儿', and avoids labeling the patient as contagious.",
          "quote": "但建议分餐制（公筷公勺）即可，不必隔离"
        },
        {
          "event_id": "lite_evt_00109",
          "explanation": "Doctor reinforces to the family that the plan can be followed without stigma and that the transplant doctor will handle the history, not the family.",
